def backfill_inquiries(apps, schema_editor):
    Inquiry = apps.get_model('services', 'ProductInquiry')
    for inquiry in Inquiry.objects.select_related('listing').iterator(chunk_size=500):
        values = {
            'public_id': uuid.uuid4(),
            'last_activity_at': inquiry.updated_at or inquiry.created_at,
            'subject': inquiry.listing.title[:180],
        }
        if inquiry.listing.organization_id:
            values['owner_organization_id'] = inquiry.listing.organization_id
        else:
            values['owner_seller_id'] = inquiry.listing.seller_id
        Inquiry.objects.filter(pk=inquiry.pk).update(**values)


